import { writeFileSync } from 'node:fs';
const cases = [];
// backslash before every printable ASCII char, in inline context
for (let i = 0x21; i <= 0x7e; i++) {
  cases.push('x \\' + String.fromCharCode(i) + ' y');
}
// whitespace / EOL / EOF
cases.push('x \\ y');        // backslash space
cases.push('x \\\ty');       // backslash tab
cases.push('x \\\ny');       // backslash newline (line ending)
cases.push('x \\');          // backslash at end of doc
cases.push('\\');            // lone backslash
cases.push('\\\\');          // two backslashes
cases.push('\\\\\\');        // three
cases.push('\\\\\\\\');      // four
writeFileSync('/tmp/cases/b2.json', JSON.stringify(cases, null, 1));
console.log(cases.length);

